package io.github.rajumark.kernelin

/**
 * Marks functions that only the code generated by the Kernelin compiler plugin calls. Using one yourself is a
 * compile error.
 */
@RequiresOptIn("Only the Kernelin compiler plugin calls this", level = RequiresOptIn.Level.ERROR)
@Retention(AnnotationRetention.BINARY)
@Target(AnnotationTarget.FUNCTION)
public annotation class KernelinGeneratedApi

/**
 * One typed kernel call, written as a normal Kotlin call inside a launch block:
 *
 * ```
 * gpu.dispatch(n) { saxpy(alpha = 2f, x = xs, y = ys) }
 * ```
 *
 * Because `saxpy(...)` is a normal call, the compiler checks the parameter names, types and count, and the IDE
 * completes them. The kernel does not run on the CPU here: the Kernelin compiler plugin turns the call into a
 * [KernelLaunch] that holds the kernel's shader ([source]) and the argument values ([scalars], [arrays]). GPU hosts
 * read it with [capture].
 *
 * A launch block must be exactly one call to a `@Kernel` function from the same module.
 */
public class KernelLaunch private constructor() {
    private var kernel: KernelSource? = null
    private var kernelCalls = 0
    private val values = HashMap<Int, Any>()
    private var cpuCall: (() -> Unit)? = null

    /** The shader of the kernel that was called. */
    public val source: KernelSource get() = kernel ?: throw IllegalStateException("No @Kernel call was recorded")

    /** The Int, Float and Boolean arguments, by parameter name (as in [KernelManifest.Param.name]). */
    public val scalars: Map<String, Any> get() = byName { !it.isBuffer }

    /** The IntArray and FloatArray arguments, by parameter name. The same array objects that were passed in. */
    public val arrays: Map<String, Any> get() = byName { it.isBuffer }

    private fun byName(keep: (KernelManifest.Param) -> Boolean): Map<String, Any> {
        val result = LinkedHashMap<String, Any>()
        source.manifest.params.forEachIndexed { i, p -> if (keep(p)) result[p.name] = values.getValue(i) }
        return result
    }

    /**
     * Runs the recorded kernel call on the CPU for ids `0 until size`, with the same argument values, like
     * `KernelinCpu.dispatch(size) { saxpy(...) }`. The arrays the kernel writes hold the results afterwards.
     * On the JVM (and Android) it uses all CPU cores; elsewhere it runs on the calling thread.
     */
    public fun runOnCpu(size: Int) {
        // Like KernelinCpu.dispatch(size): a negative size runs nothing.
        runOnCpu(size.coerceAtLeast(0), 1, 1)
    }

    /** Like [runOnCpu], for a `width x height` grid, like `KernelinCpu.dispatch(width, height) { ... }`. */
    public fun runOnCpu(width: Int, height: Int) {
        runOnCpu(width, height, 1)
    }

    /** Like [runOnCpu], for a `width x height x depth` grid. */
    public fun runOnCpu(width: Int, height: Int, depth: Int) {
        val call = checkNotNull(cpuCall) {
            "The launch of ${source.name} has no CPU call; it was compiled by an older Kernelin compiler plugin"
        }
        dispatchOnAllCores(width, height, depth, call)
    }

    /** Records how to run the same kernel call on the CPU (the arguments were evaluated once, before). */
    @KernelinGeneratedApi
    public fun cpu(call: () -> Unit) {
        cpuCall = call
    }

    /** Records the kernel. Called after its arguments, so they keep Kotlin's evaluation order. */
    @KernelinGeneratedApi
    public fun kernel(source: KernelSource) {
        kernelCalls++
        kernel = source
    }

    /** Records the argument of parameter number [index] (in Kotlin order). */
    @KernelinGeneratedApi
    public fun argument(index: Int, value: Int) {
        values[index] = value
    }

    /** Records the argument of parameter number [index] (in Kotlin order). */
    @KernelinGeneratedApi
    public fun argument(index: Int, value: Float) {
        values[index] = value
    }

    /** Records the argument of parameter number [index] (in Kotlin order). */
    @KernelinGeneratedApi
    public fun argument(index: Int, value: Boolean) {
        values[index] = value
    }

    /** Records the argument of parameter number [index] (in Kotlin order). */
    @KernelinGeneratedApi
    public fun argument(index: Int, value: IntArray) {
        values[index] = value
    }

    /** Records the argument of parameter number [index] (in Kotlin order). */
    @KernelinGeneratedApi
    public fun argument(index: Int, value: FloatArray) {
        values[index] = value
    }

    /** For GPU hosts. */
    public companion object {
        private const val NOT_RECORDED = "No @Kernel call was recorded: a launch block must be one call to a @Kernel " +
            "function, like { saxpy(alpha = 2f, x = xs, y = ys) }, and the Kernelin compiler plugin must be applied"

        /**
         * Runs a launch [block] and returns the kernel call it holds. Throws [IllegalStateException] when the block
         * did not record exactly one kernel call, which happens when the Kernelin compiler plugin is not applied.
         */
        public fun capture(block: KernelLaunch.() -> Unit): KernelLaunch {
            val launch = KernelLaunch()
            try {
                launch.block()
            } catch (e: IllegalStateException) {
                // Without the plugin the kernel body runs here, and its globalId() (or globalIdX() ...) fails outside a dispatch.
                if (launch.kernelCalls > 0 || e.message?.contains("was called outside a Kernelin dispatch") != true) throw e
                throw IllegalStateException(NOT_RECORDED, e)
            }
            check(launch.kernelCalls <= 1) { "A launch block must call exactly one @Kernel function, but it called ${launch.kernelCalls}" }
            check(launch.kernelCalls == 1) { NOT_RECORDED }
            val params = launch.source.manifest.params
            check(launch.values.size == params.size) {
                "The launch of ${launch.source.name} recorded ${launch.values.size} of ${params.size} arguments"
            }
            return launch
        }
    }
}
